from AlgorithmImports import *


class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_closes = {}
        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_red_streak = 0

    def OnData(self, data):
        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.spy not in self.previous_closes:
            self._update_state(spy_close, aapl_close)
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self._update_state(spy_close, aapl_close)
            return

        previous_spy_close = self.previous_closes[self.spy]

        spy_cross_below = (
            previous_spy_close <= self.spy_sma.Current.Value
            and spy_close > self.spy_sma.Current.Value
        )

        spy_cross_above = (
            previous_spy_close <= self.spy_sma.Current.Value
            and spy_close > self.spy_sma.Current.Value
        )

        spy_cross_down = (
            previous_spy_close >= self.spy_sma.Current.Value
            and spy_close < self.spy_sma.Current.Value
        )

        if self.spy_lot > 0 and spy_cross_down:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_cross_above:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity

        self._update_state(spy_close, aapl_close)

    def _update_state(self, spy_close, aapl_close):
        if self.aapl in self.previous_closes:
            if aapl_close < self.previous_closes[self.aapl]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.previous_closes[self.spy] = spy_close
        self.previous_closes[self.aapl] = aapl_close

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Indicators import MovingAverageType
from QuantConnect.Orders import OrderStatus


class ExactStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data):
        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.spy in data.Bars and self.spy_sma.IsReady:
            self.previous_spy_close = getattr(
                self, "_current_spy_close", None
            )
            self.previous_spy_sma = getattr(
                self, "_current_spy_sma", None
            )

            self._current_spy_close = float(data.Bars[self.spy].Close)
            self._current_spy_sma = float(self.spy_sma.Current.Value)

        if self.IsWarmingUp:
            return

        for symbol in self.symbols:
            if symbol not in data.Bars:
                return

        if (
            self.previous_spy_close is None
            or self.previous_spy_sma is None
            or not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_close = float(data.Bars[self.spy].Close)
        spy_sma = float(self.spy_sma.Current.Value)
        aapl_rsi = float(self.aapl_rsi.Current.Value)

        if (
            self.strategy_a_lot > 0
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < spy_sma
            and not self.strategy_a_pending
        ):
            self.strategy_a_pending = True
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="STRATEGY_A_SELL"
            )

        if (
            self.strategy_b_lot > 0
            and aapl_rsi > 60
            and not self.strategy_b_pending
        ):
            self.strategy_b_pending = True
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="STRATEGY_B_SELL"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > spy_sma
        ):
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue))
                / spy_close
            )

            if quantity > 0:
                self.strategy_a_pending = True
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="STRATEGY_A_BUY"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
        ):
            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(20000 / float(data.Bars[self.aapl].Close))

                if quantity > 0:
                    self.strategy_b_pending = True
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="STRATEGY_B_BUY"
                    )

        self.previous_spy_close = spy_close
        self.previous_spy_sma = spy_sma

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if order.Tag == "STRATEGY_A_BUY":
            self.strategy_a_lot += fill_quantity
        elif order.Tag == "STRATEGY_A_SELL":
            self.strategy_a_lot += fill_quantity
        elif order.Tag == "STRATEGY_B_BUY":
            self.strategy_b_lot += fill_quantity
        elif order.Tag == "STRATEGY_B_SELL":
            self.strategy_b_lot += fill_quantity
        else:
            return

        if order.Tag.startswith("STRATEGY_A_"):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_a_pending = False
        elif order.Tag.startswith("STRATEGY_B_"):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_b_pending = False

from AlgorithmImports import *


class TwoStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.last_evaluated_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        if self.last_evaluated_date == current_date:
            return

        self.last_evaluated_date = current_date

        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None and self.previous_aapl_close is not None:
            if aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or self.previous_spy_sma is None:
            spy_cross_up = False
            spy_cross_down = False
        else:
            spy_close = spy_bar.Close
            current_sma = self.spy_sma.Current.Value

            spy_cross_up = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > current_sma
            )

            spy_cross_down = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < current_sma
            )

        if spy_cross_down and self.spy_lot > 0:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            if self.aapl_lot > 0:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0

        if spy_cross_up and self.spy_lot == 0:
            price = spy_bar.Close
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / price)

            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_red_streak >= 3 and self.aapl_lot == 0:
            price = aapl_bar.Close

            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / price)

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity
